import assert from "node:assert/strict";
import { test } from "node:test";
import { SuperlogClient } from "../application/client.js";
import { FakeTransport } from "../testing/fake-transport.js";

function makeClient() {
  const transport = new FakeTransport();
  const client = new SuperlogClient({
    config: {
      token: "[REDACTED]",
      serviceName: "expo-test",
      environment: "test",
      release: "1.0.0",
      dist: "ios-sim",
      gitSha: "abc123",
      runtimeVersion: "1.0.0",
      expoUpdateId: "update-1",
      platform: "ios",
    },
    transport,
    sessionIdFactory: () => "ses_test",
  });
  return { client, transport };
}

test("logs include stable session and release attributes", () => {
  const { client, transport } = makeClient();

  client.log("hello", "info", { component: "home" });

  assert.equal(transport.logs.length, 1);
  assert.equal(transport.logs[0]?.attributes["session.id"], "ses_test");
  assert.equal(transport.logs[0]?.attributes["service.name"], "expo-test");
  assert.equal(transport.logs[0]?.attributes["service.version"], "1.0.0");
  assert.equal(transport.logs[0]?.attributes.release, "1.0.0");
  assert.equal(transport.logs[0]?.attributes.dist, "ios-sim");
  assert.equal(transport.logs[0]?.attributes["superlog.release"], "1.0.0");
  assert.equal(transport.logs[0]?.attributes["superlog.dist"], "ios-sim");
  assert.equal(transport.logs[0]?.attributes["vcs.ref.head.revision"], "abc123");
  assert.equal(transport.logs[0]?.attributes.component, "home");
});

test("configured source map identity wins over Expo metadata resource attrs", () => {
  const transport = new FakeTransport();
  const client = new SuperlogClient({
    config: {
      token: "[REDACTED]",
      serviceName: "expo-test",
      release: "expo-test-2@local",
      dist: "web-local",
      extraResourceAttributes: {
        "service.version": "1.0.0",
        "superlog.release": "wrong-release",
        "superlog.dist": "wrong-dist",
      },
    },
    transport,
    sessionIdFactory: () => "ses_test",
  });

  client.captureException(new Error("Expo SDK demo error"));

  assert.equal(transport.exceptions[0]?.attributes["service.version"], "expo-test-2@local");
  assert.equal(transport.exceptions[0]?.attributes["superlog.release"], "expo-test-2@local");
  assert.equal(transport.exceptions[0]?.attributes["superlog.dist"], "web-local");
});

test("trace correlates nested logs to the active span", async () => {
  const { client, transport } = makeClient();

  await client.trace("chat.send", async () => {
    client.log("chat_send_started");
  });

  assert.equal(transport.spans.length, 1);
  assert.equal(transport.spans[0]?.name, "chat.send");
  assert.equal(transport.spans[0]?.attributes["session.id"], "ses_test");
  assert.equal(transport.logs.length, 1);
  assert.equal(transport.logs[0]?.activeSpan?.id, "span-1");
  assert.equal(transport.spans[0]?.ended, true);
  assert.equal(transport.spans[0]?.endAttributes?.["span.status"], "ok");
});

test("an explicitly passed span correlates a log emitted after an await", async () => {
  const { client, transport } = makeClient();

  await client.trace("chat.send", async (span) => {
    await Promise.resolve();
    client.log("after_await", "info", {}, { span });
  });

  assert.equal(transport.logs.length, 1);
  assert.equal(transport.logs[0]?.message, "after_await");
  assert.equal(transport.logs[0]?.activeSpan?.id, "span-1");
});

test("an ambient log emitted with no active span carries session + route", async () => {
  const { client, transport } = makeClient();
  client.setRoute("/chat");

  client.log("ambient");

  assert.equal(transport.logs[0]?.activeSpan, undefined);
  assert.equal(transport.logs[0]?.attributes["session.id"], "ses_test");
  assert.equal(transport.logs[0]?.attributes["route.name"], "/chat");
});

test("recordNavigation tracks route changes by session", async () => {
  const { client, transport } = makeClient();

  await client.recordNavigation("/");
  await client.recordNavigation("/chat/123");

  assert.equal(transport.spans.length, 2);
  assert.equal(transport.logs.length, 2);
  assert.equal(transport.logs[1]?.attributes["navigation.from"], "/");
  assert.equal(transport.logs[1]?.attributes["navigation.to"], "/chat/123");
  assert.equal(transport.logs[1]?.attributes["route.name"], "/chat/123");
  assert.equal(transport.logs[1]?.attributes["session.id"], "ses_test");
  assert.equal(transport.logs[1]?.activeSpan?.id, "span-2");
});

test("captureException creates an error span when no span is active", () => {
  const { client, transport } = makeClient();
  const error = new Error("Cannot read property 'useMemoCache' of null");

  client.captureException(error, { component: "root_error_boundary" });

  assert.equal(transport.spans.length, 1);
  assert.equal(transport.spans[0]?.name, "exception");
  assert.equal(transport.spans[0]?.attributes["exception.type"], "Error");
  assert.equal(transport.spans[0]?.attributes["exception.message"], error.message);
  assert.equal(transport.spans[0]?.attributes["session.id"], "ses_test");
  assert.equal(transport.spans[0]?.exceptions.length, 1);
  assert.equal(transport.exceptions.length, 1);
  assert.equal(transport.exceptions[0]?.activeSpan?.id, "span-1");
});

test("captureException marks exceptions handled by default", () => {
  const { client, transport } = makeClient();

  client.captureException(new Error("boom"));

  assert.equal(transport.exceptions[0]?.attributes["exception.handled"], true);
});

test("captureException records on the active trace span", async () => {
  const { client, transport } = makeClient();
  const error = new TypeError("Network request failed");

  await client.trace("chat.send", async () => {
    client.captureException(error, { component: "chat" });
  });

  assert.equal(transport.spans.length, 1);
  assert.equal(transport.spans[0]?.name, "chat.send");
  assert.equal(transport.spans[0]?.exceptions.length, 1);
  assert.equal(transport.exceptions[0]?.activeSpan?.id, "span-1");
  assert.equal(transport.exceptions[0]?.attributes["exception.type"], "TypeError");
  assert.equal(transport.exceptions[0]?.attributes.component, "chat");
});

import assert from "node:assert/strict";
import { mkdir, mkdtemp, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";
import { discoverSourceMaps } from "../application/sourcemap-upload.js";
import { buildSourceMapArtifact } from "../domain/sourcemaps.js";

const exampleMap = JSON.stringify({
  version: 3,
  debugId: "debug-123",
  sources: ["app/index.tsx"],
  mappings: "AAAA",
});

test("buildSourceMapArtifact extracts debug id and hashes contents", () => {
  const artifact = buildSourceMapArtifact({
    mapFile: "dist/android-update.map",
    sourceMap: exampleMap,
    release: "app@1.0.0+1",
  });

  assert.equal(artifact.platform, "android");
  assert.equal(artifact.debugId, "debug-123");
  assert.equal(artifact.release, "app@1.0.0+1");
  assert.equal(artifact.sourceMapHash.length, 64);
  assert.equal(artifact.sourceMapBytes, Buffer.byteLength(exampleMap));
});

test("discoverSourceMaps finds maps recursively and pairs adjacent bundles", async () => {
  const root = await mkdtemp(join(tmpdir(), "superlog-sourcemaps-"));
  const dist = join(root, "dist");
  await mkdir(dist);
  await writeFile(join(dist, "ios-main.hbc"), "bundle");
  await writeFile(join(dist, "ios-main.hbc.map"), exampleMap);

  const artifacts = await discoverSourceMaps({
    directory: dist,
    release: "app@1.0.0+1",
    dist: "1.0.0",
  });

  assert.equal(artifacts.length, 1);
  assert.equal(artifacts[0]?.platform, "ios");
  assert.equal(artifacts[0]?.debugId, "debug-123");
  assert.match(artifacts[0]?.bundleFile ?? "", /ios-main\.hbc$/);
});

import assert from "node:assert/strict";
import { afterEach, test } from "node:test";
import { SuperlogClient } from "../application/client.js";
import { installAutomaticInstrumentation } from "../interfaces/automatic-instrumentation.js";
import { FakeTransport } from "../testing/fake-transport.js";

type ErrorUtilsTestGlobal = typeof globalThis & {
  ErrorUtils?: {
    handler?: (error: unknown, isFatal?: boolean) => void;
    getGlobalHandler: () => ((error: unknown, isFatal?: boolean) => void) | undefined;
    setGlobalHandler: (handler: (error: unknown, isFatal?: boolean) => void) => void;
  };
};

const originalFetch = globalThis.fetch;
const originalErrorUtils = (globalThis as ErrorUtilsTestGlobal).ErrorUtils;

afterEach(() => {
  globalThis.fetch = originalFetch;
  (globalThis as ErrorUtilsTestGlobal).ErrorUtils = originalErrorUtils;
});

function makeClient() {
  const transport = new FakeTransport();
  const client = new SuperlogClient({
    config: {
      token: "[REDACTED]",
      serviceName: "expo-test",
    },
    transport,
    sessionIdFactory: () => "ses_auto",
  });
  return { client, transport };
}

test("automatic console instrumentation records errors with session context", () => {
  const { client, transport } = makeClient();
  const originalConsoleError = console.error;
  console.error = () => {};
  const instrumentation = installAutomaticInstrumentation(client, {
    errors: false,
    fetch: false,
  });
  const error = new Error("console failed");

  try {
    console.error("prefix", error);
  } finally {
    instrumentation.uninstall();
    console.error = originalConsoleError;
  }

  assert.equal(transport.exceptions.length, 1);
  assert.equal(transport.exceptions[0]?.error, error);
  assert.equal(transport.exceptions[0]?.attributes["log.source"], "console");
  assert.equal(transport.exceptions[0]?.attributes["console.method"], "error");
  assert.equal(transport.exceptions[0]?.attributes["session.id"], "ses_auto");
});

test("automatic error instrumentation records React Native global errors", () => {
  const { client, transport } = makeClient();
  const previousErrors: unknown[] = [];
  const testGlobal = globalThis as ErrorUtilsTestGlobal;
  testGlobal.ErrorUtils = {
    handler: (error: unknown) => previousErrors.push(error),
    getGlobalHandler() {
      return this.handler;
    },
    setGlobalHandler(handler) {
      this.handler = handler;
    },
  };
  const instrumentation = installAutomaticInstrumentation(client, {
    console: false,
    fetch: false,
  });
  const error = new Error("root failed");

  try {
    testGlobal.ErrorUtils.handler?.(error, true);
  } finally {
    instrumentation.uninstall();
  }

  assert.equal(transport.exceptions.length, 1);
  assert.equal(transport.exceptions[0]?.error, error);
  assert.equal(transport.exceptions[0]?.attributes["event.name"], "react_native_error");
  assert.equal(transport.exceptions[0]?.attributes["exception.fatal"], true);
  assert.equal(transport.exceptions[0]?.attributes["exception.handled"], false);
  assert.equal(transport.exceptions[0]?.attributes["session.id"], "ses_auto");
  assert.deepEqual(previousErrors, [error]);
});

test("automatic fetch instrumentation creates client spans and logs responses", async () => {
  const { client, transport } = makeClient();
  globalThis.fetch = (async () => new Response("ok", { status: 201 })) as typeof fetch;
  const instrumentation = installAutomaticInstrumentation(client, {
    console: false,
    errors: false,
  });

  try {
    const response = await fetch("https://api.example.com/messages", {
      method: "post",
    });
    assert.equal(response.status, 201);
  } finally {
    instrumentation.uninstall();
  }

  assert.equal(transport.spans.length, 1);
  assert.equal(transport.spans[0]?.name, "http.client");
  assert.equal(transport.spans[0]?.attributes["url.full"], "https://api.example.com/messages");
  assert.equal(transport.spans[0]?.attributes["http.request.method"], "POST");
  assert.equal(transport.spans[0]?.attributes["session.id"], "ses_auto");
  assert.equal(transport.logs.length, 1);
  assert.equal(transport.logs[0]?.message, "fetch");
  assert.equal(transport.logs[0]?.attributes["http.response.status_code"], 201);
  assert.equal(transport.logs[0]?.activeSpan?.id, "span-1");
});

test("automatic fetch instrumentation injects W3C trace context into the request", async () => {
  const { client, transport } = makeClient();
  let capturedInit: RequestInit | undefined;
  globalThis.fetch = (async (_input: RequestInfo | URL, init?: RequestInit) => {
    capturedInit = init;
    return new Response("ok", { status: 200 });
  }) as typeof fetch;
  const instrumentation = installAutomaticInstrumentation(client, {
    console: false,
    errors: false,
  });

  try {
    await fetch("https://api.example.com/messages");
  } finally {
    instrumentation.uninstall();
  }

  const headers = new Headers(capturedInit?.headers);
  assert.ok(headers.get("traceparent"), "expected a traceparent header on the outgoing request");
  assert.equal(transport.spans[0]?.injectedCarriers.length, 1);
});

import type {
  ExceptionInput,
  LogInput,
  SpanHandle,
  StartSpanInput,
  TelemetryTransport,
} from "../application/transport.js";
import type { Attributes } from "../domain/attributes.js";

export type FakeSpanRecord = {
  id: string;
  name: string;
  attributes: Attributes;
  ended: boolean;
  endAttributes?: Attributes;
  exceptions: Array<{ error: unknown; attributes?: Attributes }>;
  injectedCarriers: Array<Record<string, string>>;
};

export class FakeTransport implements TelemetryTransport {
  spans: FakeSpanRecord[] = [];
  logs: LogInput[] = [];
  exceptions: ExceptionInput[] = [];
  private nextSpanId = 1;
  private current: SpanHandle | undefined;

  withSpan<T>(span: SpanHandle, fn: () => T): T {
    const previous = this.current;
    this.current = span;
    try {
      return fn();
    } finally {
      this.current = previous;
    }
  }

  activeSpan(): SpanHandle | undefined {
    return this.current;
  }

  startSpan(input: StartSpanInput): SpanHandle {
    const record: FakeSpanRecord = {
      id: `span-${this.nextSpanId}`,
      name: input.name,
      attributes: input.attributes,
      ended: false,
      exceptions: [],
      injectedCarriers: [],
    };
    this.nextSpanId += 1;
    this.spans.push(record);
    return {
      id: record.id,
      recordException: (error, attributes) => {
        record.exceptions.push({ error, attributes });
      },
      setAttributes: (attributes) => {
        record.attributes = { ...record.attributes, ...attributes };
      },
      end: (attributes) => {
        record.ended = true;
        record.endAttributes = attributes;
      },
      injectTraceContext: (carrier) => {
        // Deterministic fake W3C traceparent so tests can assert propagation.
        carrier.traceparent = `00-${record.id.padStart(32, "0").slice(0, 32)}-${record.id
          .padStart(16, "0")
          .slice(0, 16)}-01`;
        record.injectedCarriers.push(carrier);
      },
    };
  }

  emitLog(input: LogInput): void {
    this.logs.push(input);
  }

  emitException(input: ExceptionInput): void {
    this.exceptions.push(input);
  }
}

