export type { Attributes, AttributeValue } from "./domain/attributes.js";

export type AttributeValue = string | number | boolean | string[] | number[] | boolean[];
export type Attributes = Record<string, AttributeValue | undefined>;

export function compactAttributes(attributes: Attributes): Record<string, AttributeValue> {
  const out: Record<string, AttributeValue> = {};
  for (const [key, value] of Object.entries(attributes)) {
    if (value !== undefined) out[key] = value;
  }
  return out;
}

export function errorAttributes(error: unknown): Record<string, AttributeValue> {
  if (error instanceof Error) {
    return compactAttributes({
      "exception.type": error.name || "Error",
      "exception.message": error.message,
      "exception.stacktrace": error.stack,
    });
  }
  return {
    "exception.type": typeof error,
    "exception.message": String(error),
  };
}

export type SessionIdFactory = () => string;

export function createSessionId(now: Date = new Date(), random = defaultRandom): string {
  const timestamp = now.toISOString().replace(/[-:.TZ]/g, "").slice(0, 14);
  return `ses_${timestamp}_${random(12)}`;
}

function defaultRandom(length: number): string {
  const alphabet = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
  let out = "";
  const cryptoObject = globalThis.crypto;
  if (cryptoObject?.getRandomValues) {
    const bytes = new Uint8Array(length);
    cryptoObject.getRandomValues(bytes);
    for (const byte of bytes) out += alphabet[byte % alphabet.length];
    return out;
  }
  for (let i = 0; i < length; i += 1) {
    out += alphabet[Math.floor(Math.random() * alphabet.length)];
  }
  return out;
}

import type { Attributes } from "../domain/attributes.js";

export type Severity = "fatal" | "error" | "warning" | "info" | "debug";

export type SpanHandle = {
  id: string;
  recordException(error: unknown, attributes?: Attributes): void;
  setAttributes(attributes: Attributes): void;
  end(attributes?: Attributes): void;
  /** Inject W3C `traceparent`/`tracestate` for this span into a header carrier
   *  so downstream services join the same distributed trace. */
  injectTraceContext(carrier: Record<string, string>): void;
  otelContext?: unknown;
};

export type StartSpanInput = {
  name: string;
  attributes: Attributes;
};

export type LogInput = {
  message: string;
  severity: Severity;
  attributes: Attributes;
  activeSpan?: SpanHandle;
};

export type ExceptionInput = {
  error: unknown;
  attributes: Attributes;
  activeSpan?: SpanHandle;
};

export type TelemetryTransport = {
  startSpan(input: StartSpanInput): SpanHandle;
  /** Run `fn` with `span` as the active context, so logs/exceptions emitted
   *  synchronously inside it resolve to `span` via `activeSpan()`. */
  withSpan<T>(span: SpanHandle, fn: () => T): T;
  /** The span active in the current context, if any. */
  activeSpan(): SpanHandle | undefined;
  emitLog(input: LogInput): void;
  emitException(input: ExceptionInput): void;
  flush?(): Promise<void>;
  shutdown?(): Promise<void>;
};

import { createHash } from "node:crypto";
import { basename } from "node:path";

export type SourceMapArtifact = {
  platform: "android" | "ios" | "web" | string;
  release: string;
  dist?: string;
  debugId?: string;
  bundleFile?: string;
  mapFile: string;
  sourceMap: string;
  sourceMapHash: string;
  sourceMapBytes: number;
};

export type SourceMapJson = {
  debugId?: unknown;
  debug_id?: unknown;
  sources?: unknown;
  version?: unknown;
};

export function parseSourceMap(raw: string): SourceMapJson {
  const parsed = JSON.parse(raw) as SourceMapJson;
  if (!parsed || typeof parsed !== "object") {
    throw new Error("source map must be a JSON object");
  }
  if (!Array.isArray(parsed.sources)) {
    throw new Error("source map is missing a sources array");
  }
  return parsed;
}

export function sourceMapDebugId(sourceMap: SourceMapJson): string | undefined {
  const value = sourceMap.debugId ?? sourceMap.debug_id;
  return typeof value === "string" && value.trim() ? value.trim() : undefined;
}

export function inferPlatformFromPath(path: string): string {
  const name = basename(path).toLowerCase();
  if (name.includes("android")) return "android";
  if (name.includes("ios")) return "ios";
  if (name.includes("web")) return "web";
  return "unknown";
}

export function buildSourceMapArtifact(input: {
  mapFile: string;
  sourceMap: string;
  release: string;
  platform?: string;
  dist?: string;
  bundleFile?: string;
  debugId?: string;
}): SourceMapArtifact {
  const parsed = parseSourceMap(input.sourceMap);
  const bytes = Buffer.byteLength(input.sourceMap);
  return {
    platform: input.platform ?? inferPlatformFromPath(input.mapFile),
    release: input.release,
    dist: input.dist,
    debugId: input.debugId ?? sourceMapDebugId(parsed),
    bundleFile: input.bundleFile,
    mapFile: input.mapFile,
    sourceMap: input.sourceMap,
    sourceMapHash: createHash("sha256").update(input.sourceMap).digest("hex"),
    sourceMapBytes: bytes,
  };
}

import { useEffect } from "react";
import type { SuperlogClient } from "../application/client.js";
import { getSuperlog } from "./init.js";

type ExpoRouterModule = {
  usePathname: () => string | null;
};

let expoRouterModule: ExpoRouterModule | null | false = null;

export type SuperlogExpoRouterInstrumentationProps = {
  client?: SuperlogClient;
};

export function SuperlogExpoRouterInstrumentation({
  client,
}: SuperlogExpoRouterInstrumentationProps = {}): null {
  const pathname = useOptionalPathname();
  useEffect(() => {
    if (!pathname) return;
    void (client ?? getSuperlog()).recordNavigation(pathname);
  }, [client, pathname]);
  return null;
}

function useOptionalPathname(): string | null {
  if (expoRouterModule === null) {
    try {
      // eslint-disable-next-line @typescript-eslint/no-require-imports
      expoRouterModule = require("expo-router") as ExpoRouterModule;
    } catch {
      expoRouterModule = false;
    }
  }
  if (!expoRouterModule) return null;
  return expoRouterModule.usePathname();
}

import { promises as fs } from "node:fs";
import { join, relative } from "node:path";
import { buildSourceMapArtifact, type SourceMapArtifact } from "../domain/sourcemaps.js";

export type DiscoverSourceMapsOptions = {
  directory: string;
  release: string;
  dist?: string;
  platform?: string;
};

export async function discoverSourceMaps(options: DiscoverSourceMapsOptions): Promise<SourceMapArtifact[]> {
  const files = await walk(options.directory);
  const maps = files.filter((file) => file.endsWith(".map"));
  const artifacts: SourceMapArtifact[] = [];
  for (const mapFile of maps.sort()) {
    const sourceMap = await fs.readFile(mapFile, "utf8");
    artifacts.push(
      buildSourceMapArtifact({
        mapFile: relative(process.cwd(), mapFile),
        sourceMap,
        release: options.release,
        dist: options.dist,
        platform: options.platform,
        bundleFile: inferBundleFile(mapFile, files),
      }),
    );
  }
  return artifacts;
}

export type UploadSourceMapOptions = {
  apiUrl: string;
  projectId: string;
  token: string;
  artifact: SourceMapArtifact;
};

export async function uploadSourceMap(options: UploadSourceMapOptions): Promise<unknown> {
  const response = await fetch(`${options.apiUrl.replace(/\/+$/, "")}/api/v1/projects/${options.projectId}/sourcemaps`, {
    method: "POST",
    headers: {
      authorization: `Bearer ${options.token}`,
      "content-type": "application/json",
    },
    body: JSON.stringify({
      platform: options.artifact.platform,
      release: options.artifact.release,
      dist: options.artifact.dist,
      debugId: options.artifact.debugId,
      bundleFile: options.artifact.bundleFile,
      mapFile: options.artifact.mapFile,
      sourceMap: options.artifact.sourceMap,
      sourceMapHash: options.artifact.sourceMapHash,
      sourceMapBytes: options.artifact.sourceMapBytes,
    }),
  });
  if (!response.ok) {
    const body = await response.text().catch(() => "");
    throw new Error(`source map upload failed (${response.status}): ${body}`);
  }
  return response.json();
}

async function walk(directory: string): Promise<string[]> {
  const entries = await fs.readdir(directory, { withFileTypes: true });
  const out: string[] = [];
  for (const entry of entries) {
    const path = join(directory, entry.name);
    if (entry.isDirectory()) {
      out.push(...await walk(path));
    } else {
      out.push(path);
    }
  }
  return out;
}

function inferBundleFile(mapFile: string, files: string[]): string | undefined {
  const withoutMap = mapFile.slice(0, -4);
  const exact = files.find((file) => file === withoutMap);
  if (exact) return relative(process.cwd(), exact);
  const hbc = `${withoutMap.replace(/\.bundle$/, "")}.hbc`;
  const hbcMatch = files.find((file) => file === hbc);
  return hbcMatch ? relative(process.cwd(), hbcMatch) : undefined;
}

import { discoverSourceMaps, uploadSourceMap } from "../application/sourcemap-upload.js";

export async function runCli(argv = process.argv.slice(2)): Promise<number> {
  const [command, subcommand, ...rest] = argv;
  if (command !== "sourcemaps" || subcommand !== "upload") {
    printUsage();
    return 1;
  }

  const flags = parseFlags(rest);
  const directory = required(flags, "dir");
  const release = requiredValue(
    flags.release ?? process.env.SUPERLOG_RELEASE ?? process.env.EXPO_PUBLIC_SUPERLOG_RELEASE,
    "release",
  );
  const dist = flags.dist ?? process.env.SUPERLOG_DIST ?? process.env.EXPO_PUBLIC_SUPERLOG_DIST;
  const projectId = required(flags, "project-id");
  const token = flags.token ?? process.env.SUPERLOG_TOKEN;
  if (!token) throw new Error("missing --token or SUPERLOG_TOKEN");

  const apiUrl = flags["api-url"] ?? "https://api.superlog.sh";
  const artifacts = await discoverSourceMaps({
    directory,
    release,
    dist,
    platform: flags.platform,
  });
  if (artifacts.length === 0) {
    console.warn(`No source maps found in ${directory}`);
    return 0;
  }

  for (const artifact of artifacts) {
    const result = await uploadSourceMap({ apiUrl, projectId, token, artifact });
    console.log(JSON.stringify(result));
  }
  return 0;
}

function parseFlags(args: string[]): Record<string, string | undefined> {
  const out: Record<string, string | undefined> = {};
  for (let i = 0; i < args.length; i += 1) {
    const arg = args[i];
    if (!arg?.startsWith("--")) throw new Error(`unexpected argument: ${arg}`);
    const key = arg.slice(2);
    const next = args[i + 1];
    if (!next || next.startsWith("--")) {
      out[key] = "true";
      continue;
    }
    out[key] = next;
    i += 1;
  }
  return out;
}

function required(flags: Record<string, string | undefined>, name: string): string {
  return requiredValue(flags[name], name);
}

function requiredValue(input: string | undefined, name: string): string {
  const value = input?.trim();
  if (!value) throw new Error(`missing --${name}`);
  return value;
}

function printUsage(): void {
  console.error(
    "Usage: superlog-expo sourcemaps upload --dir dist --project-id <id> --release <release> --token <sl_public_...>",
  );
}

import { useEffect, useState, type ReactNode } from "react";
import type { SuperlogClient } from "../application/client.js";
import { SuperlogExpoRouterInstrumentation } from "./expo-router.js";
import { initSuperlog, type InitSuperlogOptions } from "./init.js";

export type SuperlogProviderProps = InitSuperlogOptions & {
  autoTrackRoutes?: boolean;
  children?: ReactNode;
  onError?: (error: unknown) => void;
};

export function SuperlogProvider({
  autoTrackRoutes = true,
  children,
  onError,
  ...options
}: SuperlogProviderProps) {
  const [client, setClient] = useState<SuperlogClient | null>(null);

  useEffect(() => {
    let cancelled = false;
    let activeClient: SuperlogClient | null = null;
    void initSuperlog(options)
      .then((nextClient) => {
        if (cancelled) {
          void nextClient.shutdown();
          return;
        }
        activeClient = nextClient;
        setClient(nextClient);
      })
      .catch((error: unknown) => {
        if (!cancelled) onError?.(error);
      });

    return () => {
      cancelled = true;
      void activeClient?.shutdown();
      setClient(null);
    };
  }, [
    options.autoInstrument,
    options.autoTrackConsole,
    options.autoTrackErrors,
    options.autoTrackFetch,
    options.dist,
    options.dsn,
    options.endpoint,
    options.environment,
    options.expoUpdateGroupId,
    options.expoUpdateId,
    options.extraResourceAttributes,
    options.gitSha,
    options.ignoredFetchUrls,
    options.platform,
    options.release,
    options.runtimeVersion,
    options.serviceName,
    options.token,
    options.useExpoMetadata,
    onError,
  ]);

  return (
    <>
      {autoTrackRoutes && client ? <SuperlogExpoRouterInstrumentation client={client} /> : null}
      {children}
    </>
  );
}

import {
  SuperlogClient,
  type SuperlogConfig,
  superlogTelemetryAttributes,
} from "../application/client.js";
import { compactAttributes } from "../domain/attributes.js";
import { readExpoMetadata } from "../infrastructure/expo-metadata.js";
import { OTelTransport } from "../infrastructure/otel/transport.js";
import {
  installAutomaticInstrumentation,
  type AutomaticInstrumentationOptions,
  type InstalledInstrumentation,
} from "./automatic-instrumentation.js";

export type InitSuperlogOptions = Omit<SuperlogConfig, "token"> & {
  /** @deprecated Use token. */
  dsn?: string;
  endpoint?: string;
  token?: string;
  autoInstrument?: boolean;
  autoTrackConsole?: boolean;
  autoTrackErrors?: boolean;
  autoTrackFetch?: boolean;
  ignoredFetchUrls?: AutomaticInstrumentationOptions["ignoredFetchUrls"];
  useExpoMetadata?: boolean;
};

let defaultClient: SuperlogClient | null = null;
let installedInstrumentation: InstalledInstrumentation | null = null;

export async function initSuperlog(options: InitSuperlogOptions): Promise<SuperlogClient> {
  const {
    autoInstrument = true,
    autoTrackConsole = true,
    autoTrackErrors = true,
    autoTrackFetch = true,
    dsn,
    endpoint,
    ignoredFetchUrls,
    token: [REDACTED],
    useExpoMetadata,
    ...configOptions
  } = options;
  const token = [REDACTED] ?? dsn;
  if (!token) throw new Error("missing Superlog public token");

  const metadata = useExpoMetadata === false ? null : await readExpoMetadata();
  const config: SuperlogConfig = {
    ...configOptions,
    token,
    release: configOptions.release ?? metadata?.release,
    dist: configOptions.dist ?? metadata?.dist ?? metadata?.updateId,
    gitSha: configOptions.gitSha ?? metadata?.gitSha,
    runtimeVersion: configOptions.runtimeVersion ?? metadata?.runtimeVersion,
    expoUpdateId: configOptions.expoUpdateId ?? metadata?.updateId,
    expoUpdateGroupId: configOptions.expoUpdateGroupId ?? metadata?.updateGroupId,
    platform: configOptions.platform ?? metadata?.platform,
    extraResourceAttributes: {
      ...metadata?.attributes,
      ...configOptions.extraResourceAttributes,
    },
  };
  const transport = new OTelTransport({
    endpoint: endpoint ?? "https://intake.superlog.sh",
    token,
    serviceName: configOptions.serviceName,
    resourceAttributes: compactAttributes(superlogTelemetryAttributes(config)),
  });
  defaultClient = new SuperlogClient({ config, transport });
  installedInstrumentation?.uninstall();
  installedInstrumentation = null;
  if (autoInstrument) {
    const instrumentation = installAutomaticInstrumentation(defaultClient, {
      console: autoTrackConsole,
      errors: autoTrackErrors,
      fetch: autoTrackFetch,
      ignoredFetchUrls: [endpoint ?? "https://intake.superlog.sh", ...(ignoredFetchUrls ?? [])],
    });
    installedInstrumentation = instrumentation;
    defaultClient.addTeardown(() => {
      instrumentation.uninstall();
      if (installedInstrumentation === instrumentation) installedInstrumentation = null;
    });
  }
  return defaultClient;
}

export function getSuperlog(): SuperlogClient {
  if (!defaultClient) {
    throw new Error("Superlog has not been initialized. Call initSuperlog() first.");
  }
  return defaultClient;
}

export function setSuperlogUser(userId: string | null): void {
  getSuperlog().setUser(userId);
}

export function setSuperlogContext(attributes: Parameters<SuperlogClient["setContext"]>[0]): void {
  getSuperlog().setContext(attributes);
}

export function log(
  message: Parameters<SuperlogClient["log"]>[0],
  severity?: Parameters<SuperlogClient["log"]>[1],
  attributes?: Parameters<SuperlogClient["log"]>[2],
  options?: Parameters<SuperlogClient["log"]>[3],
): void {
  getSuperlog().log(message, severity, attributes, options);
}

export function captureException(
  error: Parameters<SuperlogClient["captureException"]>[0],
  attributes?: Parameters<SuperlogClient["captureException"]>[1],
  options?: Parameters<SuperlogClient["captureException"]>[2],
): void {
  getSuperlog().captureException(error, attributes, options);
}

export function trace<T>(
  name: Parameters<SuperlogClient["trace"]>[0],
  fn: () => T | Promise<T>,
  options?: Parameters<SuperlogClient["trace"]>[2],
): Promise<T> {
  return getSuperlog().trace(name, fn, options);
}

import type { Attributes } from "../domain/attributes.js";

type ExpoConstantsModule = {
  default?: {
    expoConfig?: ExpoConfig;
  };
};

type ExpoConfig = {
  version?: string;
  runtimeVersion?: string | { policy?: string };
  ios?: { buildNumber?: string };
  android?: { versionCode?: number };
  slug?: string;
};

type ExpoUpdatesModule = {
  updateId?: string | null;
  isEmbeddedLaunch?: boolean;
  channel?: string | null;
  manifest?: {
    metadata?: Record<string, unknown>;
  } | null;
};

type ReactNativeModule = {
  Platform?: {
    OS?: string;
    Version?: string | number;
  };
};

type ExpoDeviceModule = {
  osName?: string | null;
  osVersion?: string | null;
  modelName?: string | null;
  modelId?: string | null;
  manufacturer?: string | null;
  brand?: string | null;
  isDevice?: boolean;
};

export type ExpoMetadata = {
  dist?: string;
  gitSha?: string;
  platform?: string;
  release?: string;
  runtimeVersion?: string;
  updateId?: string;
  updateGroupId?: string;
  channel?: string;
  attributes: Attributes;
};

export async function readExpoMetadata(): Promise<ExpoMetadata> {
  const constants = await optionalExpoConstants();
  const updates = await optionalExpoUpdates();
  const reactNative = await optionalReactNative();
  const device = await optionalExpoDevice();
  const config = constants?.default?.expoConfig;
  const runtimeVersion = runtimeVersionString(config?.runtimeVersion);
  const updateGroupId = updates?.manifest?.metadata?.updateGroup;
  const updateId = updates?.updateId ?? "embedded";
  const dist = updateId ?? updates?.channel ?? undefined;
  const gitSha = readEnv("EXPO_PUBLIC_GIT_SHA")
    ?? readEnv("EXPO_PUBLIC_SUPERLOG_GIT_SHA")
    ?? readEnv("EAS_BUILD_GIT_COMMIT_HASH");
  const platform = reactNative?.Platform?.OS ?? readEnv("EXPO_OS");
  const release = buildRelease(config);

  return {
    dist,
    gitSha,
    platform,
    release,
    runtimeVersion,
    updateId,
    updateGroupId: typeof updateGroupId === "string" ? updateGroupId : undefined,
    channel: updates?.channel ?? undefined,
    attributes: {
      "expo.app_version": config?.version,
      "expo.runtime_version": runtimeVersion,
      "expo.update_id": updateId,
      "expo.update_group_id": typeof updateGroupId === "string" ? updateGroupId : undefined,
      "expo.channel": updates?.channel ?? undefined,
      "expo.is_embedded_launch": updates?.isEmbeddedLaunch,
      "device.platform": platform,
      // Device + OS context (OTel semconv) for "fails only on iOS 17 / Pixel"
      // style triage. Sourced from expo-device when installed.
      "os.name": device?.osName ?? undefined,
      "os.version": device?.osVersion ?? reactNativeOsVersion(reactNative),
      "device.model.identifier": device?.modelId ?? undefined,
      "device.model.name": device?.modelName ?? undefined,
      "device.manufacturer": device?.manufacturer ?? device?.brand ?? undefined,
      "device.is_physical": device?.isDevice,
      "vcs.ref.head.revision": gitSha,
    },
  };
}

function reactNativeOsVersion(reactNative: ReactNativeModule | null): string | undefined {
  const version = reactNative?.Platform?.Version;
  return version === undefined ? undefined : String(version);
}

async function optionalExpoDevice(): Promise<ExpoDeviceModule | null> {
  try {
    return (await import("expo-device")) as ExpoDeviceModule;
  } catch {
    return null;
  }
}

async function optionalExpoConstants(): Promise<ExpoConstantsModule | null> {
  try {
    return await import("expo-constants") as ExpoConstantsModule;
  } catch {
    return null;
  }
}

async function optionalExpoUpdates(): Promise<ExpoUpdatesModule | null> {
  try {
    return await import("expo-updates") as ExpoUpdatesModule;
  } catch {
    return null;
  }
}

async function optionalReactNative(): Promise<ReactNativeModule | null> {
  try {
    return await import("react-native") as ReactNativeModule;
  } catch {
    return null;
  }
}

function readEnv(key: string): string | undefined {
  const value = typeof process === "undefined" ? undefined : process.env?.[key];
  return value && value.length > 0 ? value : undefined;
}

function runtimeVersionString(value: unknown): string | undefined {
  if (typeof value === "string") return value;
  if (value && typeof value === "object" && "policy" in value) {
    return String((value as { policy?: string }).policy);
  }
  return undefined;
}

function buildRelease(config: ExpoConfig | undefined): string | undefined {
  if (!config?.version) return undefined;
  const build = config.ios?.buildNumber ?? config.android?.versionCode;
  return `${config.slug ?? "expo"}@${config.version}${build ? `+${build}` : ""}`;
}
